import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';
import '../../core/theme/app_theme.dart';
class OnboardingScreen extends StatefulWidget{const OnboardingScreen({super.key});@override State<OnboardingScreen> createState()=>_OnboardingState();}
class _OnboardingState extends State<OnboardingScreen>{int page=0;final items=[('اكتشف كتابك القادم','مكتبة عربية منتقاة تناسب مزاجك واهتماماتك.'),('اقرأ بطريقتك','تحكم بالخط والحجم واللون، واحفظ اقتباساتك وملاحظاتك.'),('تقدم مع كل صفحة','تابع إنجازك واستلم توصيات ذكية مبنية على تاريخ قراءتك.')];@override Widget build(BuildContext context){return Scaffold(body:SafeArea(child:Padding(padding:const EdgeInsets.all(28),child:Column(children:[const Spacer(),Container(width:180,height:180,decoration:BoxDecoration(color:Color(0xFFE3EEE9),shape:BoxShape.circle),child:const Icon(Icons.menu_book_rounded,size:90,color:AppTheme.teal)),const SizedBox(height:48),Text(items[page].$1,textAlign:TextAlign.center,style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold,color:AppTheme.ink)),const SizedBox(height:14),Text(items[page].$2,textAlign:TextAlign.center,style:const TextStyle(color:Colors.black54,height:1.6)),const Spacer(),Row(mainAxisAlignment:MainAxisAlignment.center,children:List.generate(3,(i)=>AnimatedContainer(duration:const Duration(milliseconds:200),margin:const EdgeInsets.all(4),width:i==page?28:8,height:8,decoration:BoxDecoration(color:i==page?AppTheme.teal:Colors.black12,borderRadius:BorderRadius.circular(8))))),const SizedBox(height:28),SizedBox(width:double.infinity,child:FilledButton(onPressed:(){if(page<2){setState(()=>page++);}else{context.go('/auth');}},child:Text(page<2?'التالي':'ابدأ الآن'))),TextButton(onPressed:()=>context.go('/library'),child:const Text('تصفح كزائر'))]))));}}
